package main

import "fmt"

func base(k, l int64) int64 {
	sum := int64(0)
	for k != 0 {
		sum += k % l
		k /= l
	}
	return sum
}

func gcd(a, b int64) int64 {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func main() {
	var n int64
	fmt.Scan(&n)
	var f int64 = 0
	for i := int64(2); i < n; i++ {
		f += base(n, i)
	}
	j := gcd(f, n-2)
	fmt.Printf("%d/%d\n", f/j, (n-2)/j)
}

